const CERTAINTY_WORDS = ['clearly', 'obviously', 'definitely', 'undoubtedly', 'everyone knows'];
const HEDGE_WORDS = ['maybe', 'perhaps', 'might', 'seems', 'likely'];
const EMPATHY_WORDS = ['i understand', 'that must be hard', 'it makes sense'];
const CONSENSUS_WORDS = ['everyone knows', 'nobody can trust', 'the whole thing', 'all sides', 'cannot trust'];
const TRANSITION_WORDS = ['however', 'therefore', 'moreover', 'meanwhile', 'first', 'second', 'finally', 'on the other hand'];
const FUNCTION_WORDS = ['the', 'and', 'but', 'or', 'if', 'then', 'because', 'that', 'which', 'to', 'of', 'in', 'a', 'an'];
const SCAFFOLD_PHRASES = ['it is important to consider', 'from another perspective', 'however it is worth noting', 'we should take a balanced view', 'consider all sides carefully'];

function countMatches(text, patterns) {
  const lower = text.toLowerCase();
  return patterns.reduce((sum, p) => sum + (lower.includes(p) ? 1 : 0), 0);
}

function tokenize(text) {
  return text.toLowerCase().split(/[^a-z0-9']+/).filter(Boolean);
}

function variance(values) {
  if (!values.length) return 0;
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const v = values.reduce((acc, x) => acc + Math.pow(x - mean, 2), 0) / values.length;
  return Number(v.toFixed(2));
}

export function extractContentFeatures(post) {
  const text = `${post.title || ''} ${post.body || ''}`.trim();
  const lower = text.toLowerCase();
  const tokens = tokenize(text);
  const unique = new Set(tokens);
  const sentences = text.split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
  const sentenceLengths = sentences.map((s) => tokenize(s).length);
  const functionWordCount = tokens.filter((t) => FUNCTION_WORDS.includes(t)).length;
  const certainty = countMatches(text, CERTAINTY_WORDS);
  const hedging = countMatches(text, HEDGE_WORDS);

  return {
    id: post.id,
    subreddit: post.subreddit,
    token_count: tokens.length,
    sentence_count: sentences.length,
    lexical_diversity: tokens.length ? Number((unique.size / tokens.length).toFixed(3)) : 0,
    certainty_marker_count: certainty,
    hedging_marker_count: hedging,
    empathy_marker_count: countMatches(text, EMPATHY_WORDS),
    consensus_marker_count: countMatches(text, CONSENSUS_WORDS),
    transition_marker_count: countMatches(text, TRANSITION_WORDS),
    rhetorical_scaffold_count: countMatches(text, SCAFFOLD_PHRASES),
    self_reference_count: (text.match(/\b(i|me|my|mine)\b/gi) || []).length,
    exclamation_count: (text.match(/!/g) || []).length,
    question_count: (text.match(/\?/g) || []).length,
    mean_sentence_length: sentenceLengths.length ? Number((sentenceLengths.reduce((a, b) => a + b, 0) / sentenceLengths.length).toFixed(2)) : 0,
    sentence_length_variance: variance(sentenceLengths),
    function_word_ratio: tokens.length ? Number((functionWordCount / tokens.length).toFixed(3)) : 0,
    certainty_vs_hedge_ratio: hedging === 0 ? certainty : Number((certainty / hedging).toFixed(3)),
    abstraction_hint: countMatches(text, ['system', 'structure', 'narrative', 'context', 'coordinated', 'manipulated', 'compromised', 'process', 'outcome', 'trust']),
    normalized_text: lower
  };
}

export function scoreContent(post, features) {
  let synthetic = 0;
  let steering = 0;
  let coordination = 0;
  const reasons = [];

  if (features.lexical_diversity < 0.72) {
    synthetic += 0.12;
    reasons.push('lower lexical diversity');
  }

  if (features.mean_sentence_length > 12) {
    synthetic += 0.1;
    reasons.push('long polished sentences');
  }

  if (features.sentence_length_variance < 8 && features.sentence_count >= 2) {
    synthetic += 0.12;
    reasons.push('low sentence variation');
  }

  if (features.transition_marker_count > 0) {
    synthetic += 0.08;
    reasons.push('high discourse structure');
  }

  if (features.rhetorical_scaffold_count > 0) {
    synthetic += 0.16;
    steering += 0.08;
    reasons.push('repeated rhetorical scaffolds');
  }

  if (features.certainty_marker_count > 0) {
    steering += 0.2;
    reasons.push('certainty markers');
  }

  if (features.consensus_marker_count > 0) {
    steering += 0.25;
    coordination += 0.18;
    reasons.push('consensus framing');
  }

  if (features.abstraction_hint > 1) {
    synthetic += 0.12;
    steering += 0.12;
    reasons.push('abstraction-heavy language');
  }

  if (features.function_word_ratio > 0.45) {
    synthetic += 0.06;
    reasons.push('high function-word ratio');
  }

  if (features.exclamation_count > 1) {
    steering += 0.08;
    reasons.push('elevated emotional punctuation');
  }

  synthetic = clamp(synthetic + 0.16);
  steering = clamp(steering + 0.12);
  coordination = clamp(coordination + 0.1);

  const confidence = clamp(
    0.22 +
    (features.token_count > 12 ? 0.2 : 0) +
    (features.sentence_count > 1 ? 0.08 : 0) +
    (reasons.length * 0.07)
  );

  return {
    id: post.id,
    entity_type: 'content',
    synthetic_language_likelihood: round2(synthetic),
    narrative_steering_likelihood: round2(steering),
    coordination_likelihood: round2(coordination),
    confidence: round2(confidence),
    confidence_band: band(confidence),
    reasons: Array.from(new Set(reasons))
  };
}

function clamp(n) {
  return Math.max(0, Math.min(1, n));
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

function band(n) {
  if (n < 0.2) return 'very_low';
  if (n < 0.4) return 'low';
  if (n < 0.6) return 'moderate';
  if (n < 0.8) return 'high';
  return 'very_high';
}

function tokenize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

function stopwords() {
  return new Set(['the', 'and', 'but', 'or', 'if', 'then', 'because', 'that', 'which', 'to', 'of', 'in', 'a', 'an', 'is', 'are', 'it', 'this', 'we', 'they', 'you']);
}

function topKeywords(post, max = 8) {
  const sw = stopwords();
  const counts = new Map();
  const tokens = tokenize(`${post.title || ''} ${post.body || ''}`);
  for (const t of tokens) {
    if (sw.has(t) || t.length < 4) continue;
    counts.set(t, (counts.get(t) || 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, max)
    .map(([k]) => k);
}

function overlap(a, b) {
  const A = new Set(a);
  const B = new Set(b);
  let count = 0;
  for (const x of A) if (B.has(x)) count += 1;
  return count;
}

export function detectNarratives(posts) {
  const enriched = posts.map((post) => ({
    id: post.id,
    subreddit: post.subreddit,
    author: post.author,
    keywords: topKeywords(post)
  }));

  const groups = [];
  const used = new Set();

  for (let i = 0; i < enriched.length; i += 1) {
    if (used.has(enriched[i].id)) continue;

    const seed = enriched[i];
    const members = [seed];
    used.add(seed.id);

    for (let j = i + 1; j < enriched.length; j += 1) {
      if (used.has(enriched[j].id)) continue;
      const shared = overlap(seed.keywords, enriched[j].keywords);
      if (shared >= 2) {
        members.push(enriched[j]);
        used.add(enriched[j].id);
      }
    }

    if (members.length >= 2) {
      const keywordCounts = new Map();
      for (const m of members) {
        for (const k of m.keywords) keywordCounts.set(k, (keywordCounts.get(k) || 0) + 1);
      }

      const top = [...keywordCounts.entries()]
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
        .slice(0, 5)
        .map(([k]) => k);

      groups.push({
        id: `nar-${top.join('-').slice(0, 40) || seed.id}`,
        label: top.join(' / '),
        keywords: top,
        post_ids: members.map((m) => m.id).sort(),
        authors: Array.from(new Set(members.map((m) => m.author))).sort(),
        subreddits: Array.from(new Set(members.map((m) => m.subreddit))).sort(),
        count: members.length
      });
    }
  }

  return groups.sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
}

import { detectNarratives } from '../../narratives/src/index.js';

export function detectClusters(posts, analyses) {
  const narratives = detectNarratives(posts);
  const scoreMap = new Map(analyses.map((a) => [a.id, a]));

  return narratives.map((nar, index) => {
    const items = nar.post_ids.map((id) => scoreMap.get(id)).filter(Boolean);
    const avgSynthetic = avg(items.map((x) => x.score.synthetic_language_likelihood || 0));
    const avgSteering = avg(items.map((x) => x.score.narrative_steering_likelihood || 0));
    const avgCoordination = avg(items.map((x) => x.score.coordination_likelihood || 0));
    const sharedAuthors = nar.authors.length;
    const sharedSubs = nar.subreddits.length;
    const suspicionRank = ((avgSynthetic + avgSteering + avgCoordination) / 3) + (sharedAuthors >= 2 ? 0.05 : 0) + (sharedSubs >= 2 ? 0.05 : 0);

    return {
      id: `clu-${index + 1}`,
      narrative_id: nar.id,
      label: nar.label,
      keywords: nar.keywords,
      post_ids: nar.post_ids,
      authors: nar.authors,
      subreddits: nar.subreddits,
      size: nar.count,
      average_synthetic_language_likelihood: round2(avgSynthetic),
      average_narrative_steering_likelihood: round2(avgSteering),
      average_coordination_likelihood: round2(avgCoordination),
      suspicion_rank: round2(Math.min(1, suspicionRank))
    };
  }).sort((a, b) => b.suspicion_rank - a.suspicion_rank || b.size - a.size);
}

function avg(values) {
  if (!values.length) return 0;
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

